import { runScript } from '../../sdk/runner';
import { readFileSync } from 'fs';

// Control file (/tmp/control.txt), hot-reloaded every loop:
//   line 1: style (0=att,1=str,2=controlled,3=def)
//   line 2: target regex source
//   line 3: anchor "x,z,radius" (optional) - only fight inside this circle
function readControl(): { style: number; targets: RegExp; anchor: { x: number; z: number; r: number } | null } {
    try {
        const lines = readFileSync('/tmp/control.txt', 'utf8').trim().split('\n');
        const style = parseInt(lines[0]) || 1;
        const targets = new RegExp(lines[1] || '^(man|woman)$', 'i');
        let anchor = null;
        if (lines[2]) {
            const [x, z, r] = lines[2].split(',').map(Number);
            if (x && z && r) anchor = { x, z, r };
        }
        return { style, targets, anchor };
    } catch {
        return { style: 1, targets: /^(man|woman)$/i, anchor: null };
    }
}

